#include <vector>
#include <algorithm>

class Solution {
public:
    int maxTwoEvents(std::vector<std::vector<int>>& events) {
        std::sort(events.begin(), events.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });

        int n = events.size();
        std::vector<int> suffixMax(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            suffixMax[i] = std::max(suffixMax[i + 1], events[i][2]);
        }

        std::vector<int> starts(n);
        for (int i = 0; i < n; ++i) starts[i] = events[i][0];

        int ans = 0;
        for (int i = 0; i < n; ++i) {
            int endVal = events[i][1];
            int val = events[i][2];
            auto it = std::upper_bound(starts.begin(), starts.end(), endVal);
            int idx = std::distance(starts.begin(), it);
            ans = std::max(ans, val + suffixMax[idx]);
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int maxTwoEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));
        int n = events.length;
        int[] suffixMax = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixMax[i] = Math.max(suffixMax[i + 1], events[i][2]);
        }

        int[] starts = new int[n];
        for (int i = 0; i < n; i++) starts[i] = events[i][0];

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int end = events[i][1];
            int val = events[i][2];
            int idx = upperBound(starts, end);
            ans = Math.max(ans, val + suffixMax[idx]);
        }
        return ans;
    }

    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

/**
 * @param {number[][]} events
 * @return {number}
 */
var maxTwoEvents = function(events) {
    events.sort((a, b) => a[0] - b[0]);
    const n = events.length;
    const suffixMax = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        suffixMax[i] = Math.max(suffixMax[i + 1], events[i][2]);
    }

    const starts = events.map(e => e[0]);
    let ans = 0;

    for (let i = 0; i < n; i++) {
        const end = events[i][1];
        const val = events[i][2];
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (starts[mid] <= end) lo = mid + 1;
            else hi = mid;
        }
        ans = Math.max(ans, val + suffixMax[lo]);
    }
    return ans;
};
